insert into public.products (
  brand_id, slug, title_zh_hk, title_zh_cn, title_en,
  description_zh_hk, description_zh_cn, description_en,
  price_hkd, stock, image_paths, status, sort
)
select b.id, x.slug, x.title_zh_hk, x.title_zh_cn, x.title_en,
  x.description_zh_hk, x.description_zh_cn, x.description_en,
  x.price_hkd, x.stock, x.image_paths, 'on_sale', x.sort
from jsonb_to_recordset($json$[{"brand_slug":"epionce","slug":"anti-inflammatory-acne-cream","title_zh_hk":"\u6297\u708e\u6de8\u75d8\u971c","title_zh_cn":"\u6297\u708e\u51c0\u75d8\u971c","title_en":"Anti-Inflammatory Acne Cream","description_zh_hk":"<p>\u5168\u65b0\u91dd\u5c0d\u6697\u7621\u8b77\u7406\u7684\u6de8\u75d8\u971c\uff0c\u7d93\u81e8\u5e8a \u6e2c\u8a66\uff0c\u6709\u6548\u70ba\u9762\u90e8\u548c\u8eab\u9ad4\u4e0a\u7684\u9811\u56fa\u6697\u7621\u63d0\u4f9b\u5feb\u901f\u6539\u5584\uff0c\u800c\u4e14\u7121\u523a\u6fc0\u548c\u4e0d\u6703\u5f15\u8d77\u808c\u819a\u4e7e\u71e5\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u91dd\u5c0d\u9762\u90e8\u53ca\u8eab\u9ad4\u6697\u7621\uff0c\u6709\u6548\u5feb\u901f\u91cd\u9ede\u6539\u5584</p>\n<p>\u2013 \u6eab\u548c\u6210\u4efd\u8a3c\u5be6\u6709\u6548\u6539\u5584\u6697\u7621\u4f46\u7121\u523a\u6fc0</p>\n<p>\u2013 \u6ef2\u900f\u81f3\u6bdb\u5b54\u5e95\u5c64\uff0c\u6709\u52a9\u6f54\u6de8\u6bdb\u5b54\u53ca\u9810\u9632\u6697\u7621\u5f62\u6210</p>\n<p>\u2013 \u6709\u52a9\u6e1b\u5c11\u75a4\u75d5\u5f62\u6210\u3001\u6cdb\u7d05\u548c\u8272\u7d20\u6c88\u6fb1</p>\n<p>\u2013 \u81e8\u5e8a\u8b49\u660e\u80fd\u91dd\u5c0d\u55ae\u500b\u6216\u591a\u500b\u808c\u819a\u75c5\u8b8a</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u786b\u78fa4%</p>\n<p>\u2013 \u55ae\u4e59\u9178\u9593\u82ef\u4e8c\u915a\u916f3%</p>\n<p>\u2013 \u8584\u8377</p>\n<p>\u2013 \u7559\u862d\u9999\u6cb9</p>\n<p>\u2013 \u58ec\u4e8c\u9178</p>\n<p>\u2013 \u8475\u82b1\u7c7d\u6cb9</p>\n<p>\u2013 \u6930\u5b50\u6cb9</p>\n<p>\u2013 \u7c73\u7ce0</p>\n<p>\u2013 \u8fa3\u6912</p>\n<p>\u2013 \u5421\u5576\u786b\u916e\u92c5</p>","description_zh_cn":"<p>\u5168\u65b0\u9488\u5bf9\u6697\u75ae\u62a4\u7406\u7684\u51c0\u75d8\u971c\uff0c\u7ecf\u4e34\u5e8a \u6d4b\u8bd5\uff0c\u6709\u6548\u4e3a\u9762\u90e8\u548c\u8eab\u4f53\u4e0a\u7684\u987d\u56fa\u6697\u75ae\u63d0\u4f9b\u5feb\u901f\u6539\u5584\uff0c\u800c\u4e14\u65e0\u523a\u6fc0\u548c\u4e0d\u4f1a\u5f15\u8d77\u808c\u80a4\u5e72\u71e5\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u9488\u5bf9\u9762\u90e8\u53ca\u8eab\u4f53\u6697\u75ae\uff0c\u6709\u6548\u5feb\u901f\u91cd\u70b9\u6539\u5584</p>\n<p>\u2013 \u6e29\u548c\u6210\u4efd\u8bc1\u5b9e\u6709\u6548\u6539\u5584\u6697\u75ae\u4f46\u65e0\u523a\u6fc0</p>\n<p>\u2013 \u6e17\u900f\u81f3\u6bdb\u5b54\u5e95\u5c42\uff0c\u6709\u52a9\u6d01\u51c0\u6bdb\u5b54\u53ca\u9884\u9632\u6697\u75ae\u5f62\u6210</p>\n<p>\u2013 \u6709\u52a9\u51cf\u5c11\u75a4\u75d5\u5f62\u6210\u3001\u6cdb\u7ea2\u548c\u8272\u7d20\u6c89\u6dc0</p>\n<p>\u2013 \u4e34\u5e8a\u8bc1\u660e\u80fd\u9488\u5bf9\u5355\u4e2a\u6216\u591a\u4e2a\u808c\u80a4\u75c5\u53d8</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u786b\u78fa4%</p>\n<p>\u2013 \u5355\u4e59\u9178\u95f4\u82ef\u4e8c\u915a\u916f3%</p>\n<p>\u2013 \u8584\u8377</p>\n<p>\u2013 \u7559\u5170\u9999\u6cb9</p>\n<p>\u2013 \u58ec\u4e8c\u9178</p>\n<p>\u2013 \u8475\u82b1\u7c7d\u6cb9</p>\n<p>\u2013 \u6930\u5b50\u6cb9</p>\n<p>\u2013 \u7c73\u7ce0</p>\n<p>\u2013 \u8fa3\u6912</p>\n<p>\u2013 \u5421\u5576\u786b\u916e\u950c</p>","description_en":"<p>Clinically tested acne cream for stubborn facial and body breakouts. Fast improvement without irritation or dryness.</p>\n<p>Key benefits</p>\n<p>\u2013 Rapid, targeted improvement for face and body acne</p>\n<p>\u2013 Gentle, proven actives without irritation</p>\n<p>\u2013 Penetrates pores to help cleanse and prevent new spots</p>\n<p>\u2013 Helps reduce scarring, redness and pigmentation</p>\n<p>\u2013 Clinically shown for single or multiple lesions</p>\n<p>Key ingredients</p>\n<p>\u2013 Sulfur 4%</p>\n<p>\u2013 Resorcinol monoacetate 3%</p>\n<p>\u2013 Peppermint</p>\n<p>\u2013 Spearmint oil</p>\n<p>\u2013 Azelaic acid</p>\n<p>\u2013 Sunflower seed oil</p>\n<p>\u2013 Coconut oil</p>\n<p>\u2013 Rice bran</p>\n<p>\u2013 Capsicum</p>\n<p>\u2013 Zinc pyrithione</p>","price_hkd":385,"stock":20,"image_paths":["/images/products/prod-17@2x.jpg"],"sort":213}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
  description_zh_hk text, description_zh_cn text, description_en text,
  price_hkd numeric, stock int, image_paths jsonb, sort int
)
join public.brands b on b.slug = x.brand_slug;